import itertools

def solve_small(cards):
    # cards is a sorted list of cards
    # Grogg (G) minimizes |S1-S2|, Winnie (W) maximizes |S1-S2|
    # State: (remaining_cards, current_diff, turn_player)
    # turn_player: 0 for G, 1 for W
    memo = {}

    def get_value(remaining_cards, diff, turn_player):
        state = (tuple(sorted(remaining_cards)), diff, turn_player)
        if state in memo:
            return memo[state]

        if not remaining_cards:
            return abs(diff)

        if turn_player == 0: # Grogg's turn (Minimizer)
            best_val = float('inf')
            for card in remaining_cards:
                # Grogg can put card in P1 or P2
                res1 = get_value(tuple(c for c in remaining_cards if c != card), diff + card, 1)
                res2 = get_value(tuple(c for c in remaining_cards if c != card), diff - card, 1)
                best_val = min(best_val, res1, res2)
            memo[state] = best_val
            return best_val
        else: # Winnie's turn (Maximizer)
            best_val = float('-inf')
            for card in remaining_cards:
                # Winnie can put card in P1 or P2
                res1 = get_value(tuple(c for c in remaining_cards if c != card), diff + card, 0)
                res2 = get_value(tuple(c for c in remaining_cards if c != card), diff - card, 0)
                best_val = max(best_val, res1, res2)
            memo[state] = best_val
            return best_val

    return get_value(tuple(cards), 0, 0)

for n in range(2, 11, 2):
    print(f"n={n}, result={solve_small(list(range(1, n+1)))}")

