def solve_for_first_move(cards, first_card, first_pile):
    memo = {}
    def get_value(remaining_cards, diff, turn_player):
        state = (remaining_cards, diff, turn_player)
        if state in memo:
            return memo[state]
        if not remaining_cards:
            return abs(diff)
        if turn_player == 0: # Grogg
            best_val = float('inf')
            for i in range(len(remaining_cards)):
                card = remaining_cards[i]
                next_cards = remaining_cards[:i] + remaining_cards[i+1:]
                best_val = min(best_val, get_value(next_cards, diff + card, 1), get_value(next_cards, diff - card, 1))
            memo[state] = best_val
            return best_val
        else: # Winnie
            best_val = float('-inf')
            for i in range(len(remaining_cards)):
                card = remaining_cards[i]
                next_cards = remaining_cards[:i] + remaining_cards[i+1:]
                best_val = max(best_val, get_value(next_cards, diff + card, 0), get_value(next_cards, diff - card, 0))
            memo[state] = best_val
            return best_val

    # G's first move is fixed
    remaining = tuple(c for c in cards if c != first_card)
    diff = first_card if first_pile == 1 else -first_card
    return get_value(remaining, diff, 1)

